{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.SNITCH_SIZE_CHANNEL_INVENTORY AS WITH eligible_skus AS ( SELECT DISTINCT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP FROM SNITCH_DB.MAPLEMONK.OMNI_BUFFER_SKUS WHERE UPPER(TRIM(SKU_GROUP)) LIKE \'4MBG%\' OR UPPER(TRIM(SKU_GROUP)) LIKE \'4B%\' ), latest_question_records AS ( SELECT * FROM SNITCH_DB.MAPLEMONK.QUESTION_2190 QUALIFY ROW_NUMBER() OVER ( PARTITION BY _AIRBYTE_QUESTION_2190_HASHID ORDER BY _AIRBYTE_NORMALIZED_AT DESC NULLS LAST, _AIRBYTE_EMITTED_AT DESC NULLS LAST ) = 1 ), question_normalized AS ( SELECT REGEXP_REPLACE( UPPER(TRIM(q.SKU)), \'-[^-]+$\', \'\' ) AS SKU_GROUP, CASE WHEN REGEXP_SUBSTR(UPPER(TRIM(q.SKU)), \'[^-]+$\') IN (\'3XL\', \'40\') THEN \'40/3XL\' WHEN REGEXP_SUBSTR(UPPER(TRIM(q.SKU)), \'[^-]+$\') IN (\'4XL\', \'42\') THEN \'42/4XL\' WHEN REGEXP_SUBSTR(UPPER(TRIM(q.SKU)), \'[^-]+$\') IN (\'5XL\', \'44\') THEN \'44/5XL\' WHEN REGEXP_SUBSTR(UPPER(TRIM(q.SKU)), \'[^-]+$\') IN (\'6XL\', \'46\') THEN \'46/6XL\' WHEN REGEXP_SUBSTR(UPPER(TRIM(q.SKU)), \'[^-]+$\') IN (\'7XL\', \'48\') THEN \'48/7XL\' WHEN REGEXP_SUBSTR(UPPER(TRIM(q.SKU)), \'[^-]+$\') IN (\'8XL\', \'50\') THEN \'50/8XL\' ELSE NULL END AS SIZE_LABEL, UPPER(TRIM(q.LOCATION)) AS LOCATION, COALESCE( TRY_TO_NUMBER(TO_VARCHAR(q.INVENTORY_TOTAL)), 0 ) AS INVENTORY FROM latest_question_records q INNER JOIN eligible_skus e ON REGEXP_REPLACE( UPPER(TRIM(q.SKU)), \'-[^-]+$\', \'\' ) = e.SKU_GROUP WHERE UPPER(TRIM(q.LOCATION)) LIKE \'BOH-%\' OR UPPER(TRIM(q.LOCATION)) LIKE \'BOHQ-%\' ), channel_inventory AS ( SELECT SKU_GROUP, SIZE_LABEL, SUM( CASE WHEN LOCATION LIKE \'BOH-%\' AND LOCATION NOT LIKE \'BOHQ-%\' THEN INVENTORY ELSE 0 END ) AS OMNI_INVENTORY, SUM( CASE WHEN LOCATION LIKE \'BOHQ-%\' THEN INVENTORY ELSE 0 END ) AS QUICK_INVENTORY FROM question_normalized WHERE SIZE_LABEL IS NOT NULL GROUP BY SKU_GROUP, SIZE_LABEL ), warehouse_raw AS ( SELECT UPPER(TRIM(\"Item SkuCode\")) AS ITEM_SKU, COALESCE( NULLIF(UPPER(TRIM(SIZE)), \'\'), REGEXP_SUBSTR( UPPER(TRIM(\"Item SkuCode\")), \'[^-]+$\' ) ) AS SIZE_TOKEN, \"Category Name\" AS CATEGORY_NAME, COALESCE( TRY_TO_NUMBER(TO_VARCHAR(INVENTORY)), 0 ) AS INVENTORY, \"DATE\" AS SNAPSHOT_DATE FROM SNITCH_DB.MAPLEMONK.SNITCH_FINAL_INVENTORY_WH2 WHERE UPPER(TRIM(\"Item SkuCode\")) LIKE \'4MBG%\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'4B%\' ), warehouse_normalized AS ( SELECT CASE WHEN ITEM_SKU LIKE \'%-\' || SIZE_TOKEN THEN REGEXP_REPLACE( ITEM_SKU, \'-[^-]+$\', \'\' ) ELSE ITEM_SKU END AS SKU_GROUP, CASE WHEN SIZE_TOKEN IN (\'3XL\', \'40\') THEN \'40/3XL\' WHEN SIZE_TOKEN IN (\'4XL\', \'42\') THEN \'42/4XL\' WHEN SIZE_TOKEN IN (\'5XL\', \'44\') THEN \'44/5XL\' WHEN SIZE_TOKEN IN (\'6XL\', \'46\') THEN \'46/6XL\' WHEN SIZE_TOKEN IN (\'7XL\', \'48\') THEN \'48/7XL\' WHEN SIZE_TOKEN IN (\'8XL\', \'50\') THEN \'50/8XL\' ELSE NULL END AS SIZE_LABEL, CATEGORY_NAME, INVENTORY, SNAPSHOT_DATE FROM warehouse_raw ), latest_warehouse_date AS ( SELECT MAX(SNAPSHOT_DATE) AS SNAPSHOT_DATE FROM warehouse_normalized ), warehouse_inventory AS ( SELECT w.SKU_GROUP, w.SIZE_LABEL, MAX(w.CATEGORY_NAME) AS CATEGORY_NAME, SUM(w.INVENTORY) AS WAREHOUSE_INVENTORY FROM warehouse_normalized w INNER JOIN latest_warehouse_date d ON w.SNAPSHOT_DATE = d.SNAPSHOT_DATE WHERE w.SIZE_LABEL IS NOT NULL GROUP BY w.SKU_GROUP, w.SIZE_LABEL ), combined AS ( SELECT COALESCE(c.SKU_GROUP, w.SKU_GROUP) AS SKU_GROUP, COALESCE(c.SIZE_LABEL, w.SIZE_LABEL) AS SIZE_LABEL, w.CATEGORY_NAME, COALESCE(c.OMNI_INVENTORY, 0) AS OMNI_INVENTORY, COALESCE(c.QUICK_INVENTORY, 0) AS QUICK_INVENTORY, COALESCE(w.WAREHOUSE_INVENTORY, 0) AS WAREHOUSE_INVENTORY FROM channel_inventory c FULL OUTER JOIN warehouse_inventory w ON c.SKU_GROUP = w.SKU_GROUP AND c.SIZE_LABEL = w.SIZE_LABEL ) SELECT SKU_GROUP, MAX(CATEGORY_NAME) AS CATEGORY_NAME, SUM(CASE WHEN SIZE_LABEL = \'40/3XL\' THEN OMNI_INVENTORY ELSE 0 END) AS \"40/3XL_OMNI\", SUM(CASE WHEN SIZE_LABEL = \'40/3XL\' THEN QUICK_INVENTORY ELSE 0 END) AS \"40/3XL_QUICK\", SUM(CASE WHEN SIZE_LABEL = \'40/3XL\' THEN WAREHOUSE_INVENTORY ELSE 0 END) AS \"40/3XL_WAREHOUSE\", SUM(CASE WHEN SIZE_LABEL = \'40/3XL\' THEN OMNI_INVENTORY + QUICK_INVENTORY + WAREHOUSE_INVENTORY ELSE 0 END) AS \"40/3XL_TOTAL\", SUM(CASE WHEN SIZE_LABEL = \'42/4XL\' THEN OMNI_INVENTORY ELSE 0 END) AS \"42/4XL_OMNI\", SUM(CASE WHEN SIZE_LABEL = \'42/4XL\' THEN QUICK_INVENTORY ELSE 0 END) AS \"42/4XL_QUICK\", SUM(CASE WHEN SIZE_LABEL = \'42/4XL\' THEN WAREHOUSE_INVENTORY ELSE 0 END) AS \"42/4XL_WAREHOUSE\", SUM(CASE WHEN SIZE_LABEL = \'42/4XL\' THEN OMNI_INVENTORY + QUICK_INVENTORY + WAREHOUSE_INVENTORY ELSE 0 END) AS \"42/4XL_TOTAL\", SUM(CASE WHEN SIZE_LABEL = \'44/5XL\' THEN OMNI_INVENTORY ELSE 0 END) AS \"44/5XL_OMNI\", SUM(CASE WHEN SIZE_LABEL = \'44/5XL\' THEN QUICK_INVENTORY ELSE 0 END) AS \"44/5XL_QUICK\", SUM(CASE WHEN SIZE_LABEL = \'44/5XL\' THEN WAREHOUSE_INVENTORY ELSE 0 END) AS \"44/5XL_WAREHOUSE\", SUM(CASE WHEN SIZE_LABEL = \'44/5XL\' THEN OMNI_INVENTORY + QUICK_INVENTORY + WAREHOUSE_INVENTORY ELSE 0 END) AS \"44/5XL_TOTAL\", SUM(CASE WHEN SIZE_LABEL = \'46/6XL\' THEN OMNI_INVENTORY ELSE 0 END) AS \"46/6XL_OMNI\", SUM(CASE WHEN SIZE_LABEL = \'46/6XL\' THEN QUICK_INVENTORY ELSE 0 END) AS \"46/6XL_QUICK\", SUM(CASE WHEN SIZE_LABEL = \'46/6XL\' THEN WAREHOUSE_INVENTORY ELSE 0 END) AS \"46/6XL_WAREHOUSE\", SUM(CASE WHEN SIZE_LABEL = \'46/6XL\' THEN OMNI_INVENTORY + QUICK_INVENTORY + WAREHOUSE_INVENTORY ELSE 0 END) AS \"46/6XL_TOTAL\", SUM(CASE WHEN SIZE_LABEL = \'48/7XL\' THEN OMNI_INVENTORY ELSE 0 END) AS \"48/7XL_OMNI\", SUM(CASE WHEN SIZE_LABEL = \'48/7XL\' THEN QUICK_INVENTORY ELSE 0 END) AS \"48/7XL_QUICK\", SUM(CASE WHEN SIZE_LABEL = \'48/7XL\' THEN WAREHOUSE_INVENTORY ELSE 0 END) AS \"48/7XL_WAREHOUSE\", SUM(CASE WHEN SIZE_LABEL = \'48/7XL\' THEN OMNI_INVENTORY + QUICK_INVENTORY + WAREHOUSE_INVENTORY ELSE 0 END) AS \"48/7XL_TOTAL\", SUM(CASE WHEN SIZE_LABEL = \'50/8XL\' THEN OMNI_INVENTORY ELSE 0 END) AS \"50/8XL_OMNI\", SUM(CASE WHEN SIZE_LABEL = \'50/8XL\' THEN QUICK_INVENTORY ELSE 0 END) AS \"50/8XL_QUICK\", SUM(CASE WHEN SIZE_LABEL = \'50/8XL\' THEN WAREHOUSE_INVENTORY ELSE 0 END) AS \"50/8XL_WAREHOUSE\", SUM(CASE WHEN SIZE_LABEL = \'50/8XL\' THEN OMNI_INVENTORY + QUICK_INVENTORY + WAREHOUSE_INVENTORY ELSE 0 END) AS \"50/8XL_TOTAL\", SUM(OMNI_INVENTORY) AS SKU_OMNI_TOTAL, SUM(QUICK_INVENTORY) AS SKU_QUICK_TOTAL, SUM(WAREHOUSE_INVENTORY) AS SKU_WAREHOUSE_TOTAL, SUM( OMNI_INVENTORY + QUICK_INVENTORY + WAREHOUSE_INVENTORY ) AS SKU_TOTAL FROM combined WHERE SIZE_LABEL IN ( \'40/3XL\', \'42/4XL\', \'44/5XL\', \'46/6XL\', \'48/7XL\', \'50/8XL\' ) GROUP BY SKU_GROUP ORDER BY SKU_GROUP;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            